function MaxSubArray(nums: int[]) -> int {
  let n = nums.length();
  let best = nums[0];
  let cur = nums[0];
  let i = 1;
  while (i < n) {
    let x = nums[i];
    if (cur + x > x) {
      cur = cur + x;
    } else {
      cur = x;
    }
    if (cur > best) {
      best = cur;
    }
    i += 1;
  }
  return best;
}
